// Inputs esperados
const periodo = $json.periodo || 'Periodo no especificado';
const chartUrl = $json.chart_url || '';
const fechaStr = new Date().toISOString().split('T')[0];

function formatearMarkdownAHTML(markdown) {
  if (!markdown) return '';
  let html = String(markdown)
    .replace(/<img[^>]*>/gi, '')
    // Títulos y subtítulos con espaciado operativo limpio
    .replace(/^##\s+(.*)$/gm, '<h2 style="color:#1e3a8a; border-bottom:2px solid #e5e7eb; padding-bottom:6px; margin-top:24px; margin-bottom:12px; font-size:16px;">$1</h2>')
    .replace(/^###\s+(.*)$/gm, '<div style="background:#f1f5f9; border-left:4px solid #1e40af; padding:8px 12px; margin-top:16px; margin-bottom:8px; border-radius:0 4px 4px 0;"><h3 style="color:#1e40af; margin:0; font-size:14px;">$1</h3></div>')
    .replace(/^####\s+(.*)$/gm, '<h4 style="color:#374151; margin-top:10px; margin-bottom:4px; font-size:13px; font-weight:bold;">$1</h4>')
    .replace(/\*\*(.*?)\*\*/g, '<strong>$1</strong>')
    // Viñetas sin numeración artificial (evita el "1.") y con sangrado ordenado
    .replace(/^\s*-\s+\[[ x]\]\s+(.*)$/gm, '<li style="margin-bottom:6px; color:#374151; list-style-type:disc;">$1</li>')
    .replace(/^\s*-\s+(.*)$/gm, '<li style="margin-bottom:6px; color:#374151; list-style-type:disc;">$1</li>')
    .replace(/^\s*\*\s+(.*)$/gm, '<li style="margin-bottom:6px; color:#374151; list-style-type:disc;">$1</li>')
    .replace(/^---$/gm, '<hr style="border:0; border-top:1px solid #e5e7eb; margin:16px 0;" />');

  // Envoltura estricta en <ul> con margen
  html = html.replace(/(<li[\s\S]*?<\/li>)+/g, '<ul style="padding-left:22px; margin:8px 0 14px 0;">$&</ul>');

  return html.split('\n').map(l => {
    const trimmed = l.trim();
    if (!trimmed) return '';
    if (trimmed.startsWith('<h') || trimmed.startsWith('<div') || trimmed.startsWith('<ul') || trimmed.startsWith('<li') || trimmed.startsWith('<hr')) {
      return trimmed;
    }
    return `<p style="margin:6px 0 8px 0; line-height:1.5;">${trimmed}</p>`;
  }).join('');
}

const narrativaLLM = formatearMarkdownAHTML($json.narrativa_html);

function parseSeguro(valor, fallback) {
  if (!valor || String(valor).trim() === '') return fallback;
  try { return typeof valor === 'string' ? JSON.parse(valor) : valor; } catch (e) { return fallback; }
}

const est = parseSeguro($json.estadisticas, {});
const ctxExt = parseSeguro($json.contexto_externo, {});
const tablaDiaria = parseSeguro($json.tabla_diaria, []);
const tablaHistorico = parseSeguro($json.tabla_historico, []);
const tablaCompetencia = parseSeguro($json.tabla_competencia, []);

let totalPeriodo = {};
try { 
  const mn = parseSeguro($json.metricas_negocio, {});
  totalPeriodo = mn.total || {};
} catch (e) {}

let serieDiariaMetricas = [];
try { 
  const mn = parseSeguro($json.metricas_negocio, {});
  serieDiariaMetricas = mn.diario || [];
} catch (e) {}

let ingresosResumen = parseSeguro($json.ingresos_resumen, {});

function pct(v) { return v !== undefined && v !== null ? (Number(v) * 100).toFixed(1) + '%' : 'N/A'; }
function pctDirecto(v) { return v !== undefined && v !== null ? Number(v).toFixed(1) + '%' : 'N/A'; }
function formatearFechaCorta(iso) {
  if (!iso) return iso;
  const d = new Date(iso + 'T00:00:00');
  return d.toLocaleDateString('es-ES', { day: 'numeric', month: 'short' });
}

function extraerPrecioNumerico(val) {
  if (val === null || val === undefined) return null;
  if (typeof val === 'number') return !isNaN(val) && val > 0 ? val : null;
  if (typeof val === 'object') {
    const p = val.precio ?? val.rate ?? val.valor ?? val.amount ?? null;
    return extraerPrecioNumerico(p);
  }
  const str = String(val).trim();
  const match = str.match(/[\d]+(?:[.,]\d+)?/);
  if (!match) return null;
  const num = parseFloat(match[0].replace(',', '.'));
  return !isNaN(num) && num > 0 ? num : null;
}

// ----------------------------------------------------
// 1. CÁLCULO SEGURO DEL PICKUP MEDIO (Solución a N/A)
// ----------------------------------------------------
let pickupCalculado = totalPeriodo.pickup_pace?.pickup_7_medio ?? totalPeriodo.pickup_pace?.pickup_medio_7d ?? null;

if (pickupCalculado === null || isNaN(pickupCalculado)) {
  const pickupsValidos = (Array.isArray(tablaDiaria) ? tablaDiaria : [])
    .map(d => parseFloat(d.pickup_7))
    .filter(v => !isNaN(v) && v !== null);

  if (pickupsValidos.length > 0) {
    pickupCalculado = (pickupsValidos.reduce((a, b) => a + b, 0) / pickupsValidos.length).toFixed(1);
  }
}
const pickupPropio = (pickupCalculado !== null && !isNaN(pickupCalculado)) ? `${Number(pickupCalculado).toFixed(1)} hab` : '0.0 hab';

// ----------------------------------------------------
// 2. CONTEXTO EXTERNO
// ----------------------------------------------------
const totalDias = Array.isArray(tablaDiaria) ? tablaDiaria.length : 0;
const diasLluvia = Array.isArray(tablaDiaria) ? tablaDiaria.filter(d => d.lluvia === 'Sí').length : 0;

const precipitaciones = (Array.isArray(tablaDiaria) ? tablaDiaria : [])
  .map(d => parseFloat(d.precipitacion_mm))
  .concat(serieDiariaMetricas.map(d => parseFloat((d.contexto_externo?.clima || d.clima)?.precipitacion)))
  .filter(v => !isNaN(v) && v !== null);
const totalMm = precipitaciones.length ? precipitaciones.reduce((a, b) => a + b, 0).toFixed(1) : '0.0';

const tempsMax = (Array.isArray(tablaDiaria) ? tablaDiaria : [])
  .map(d => parseFloat(d.temp_max))
  .concat(serieDiariaMetricas.map(d => parseFloat((d.contexto_externo?.clima || d.clima)?.temp_max ?? d.temp_max)))
  .filter(v => !isNaN(v) && v !== null);

const tempsMin = (Array.isArray(tablaDiaria) ? tablaDiaria : [])
  .map(d => parseFloat(d.temp_min))
  .concat(serieDiariaMetricas.map(d => parseFloat((d.contexto_externo?.clima || d.clima)?.temp_min ?? d.temp_min)))
  .filter(v => !isNaN(v) && v !== null);

const maxTemp = tempsMax.length ? Math.max(...tempsMax).toFixed(1) + ' °C' : 'N/A';
const minTemp = tempsMin.length ? Math.min(...tempsMin).toFixed(1) + ' °C' : 'N/A';

const preciosComp = Array.isArray(tablaCompetencia)
  ? tablaCompetencia.map(h => extraerPrecioNumerico(h.precio ?? h.tarifa ?? h.rate)).filter(p => p !== null)
  : [];
const maxPrecioComp = preciosComp.length ? Math.max(...preciosComp).toFixed(0) + ' €' : 'N/A';
const minPrecioComp = preciosComp.length ? Math.min(...preciosComp).toFixed(0) + ' €' : 'N/A';

const ratingsComp = Array.isArray(tablaCompetencia)
  ? tablaCompetencia.map(h => parseFloat(h.rating)).filter(r => !isNaN(r) && r > 0)
  : [];
const ratingMedioComp = ratingsComp.length ? (ratingsComp.reduce((a, b) => a + b, 0) / ratingsComp.length).toFixed(1) : 'N/A';

const bloqueContexto = `
<div style="background:#f8fafc; border:1px solid #e2e8f0; border-radius:8px; padding:12px 16px; margin: 16px 0;">
  <h3 style="margin: 0 0 8px 0; color:#1e3a8a; font-size:14px;">Contexto del Mercado y Entorno</h3>
  <p style="margin:0; font-size:13px; color:#475569; line-height:1.6;">
    🗓️ <strong>Festivos:</strong> ${ctxExt.dias_festivos ?? 0}d &nbsp;|&nbsp; 
    🎒 <strong>Vacaciones escolares:</strong> ${ctxExt.dias_vacaciones_escolares ?? 0}d &nbsp;|&nbsp; 
    🌡️ <strong>Temp. máx/mín:</strong> ${maxTemp} / ${minTemp} &nbsp;|&nbsp; 
    🌧️ <strong>Lluvia:</strong> ${diasLluvia}/${totalDias}d (${totalMm} mm) &nbsp;|&nbsp; 
    🏨 <strong>Precios comp. (mín/máx):</strong> ${minPrecioComp} - ${maxPrecioComp} (⭐ ${ratingMedioComp})
  </p>
</div>`;

// ----------------------------------------------------
// 3. INGRESOS DEL PERIODO (ARRIBA)
// ----------------------------------------------------
let bloqueIngresos = '';
if (ingresosResumen && ingresosResumen.totales_previstos !== undefined && ingresosResumen.totales_previstos !== null) {
  const yoyTexto = ingresosResumen.yoy_pct !== null && ingresosResumen.yoy_pct !== undefined
    ? `${ingresosResumen.yoy_pct >= 0 ? '+' : ''}${ingresosResumen.yoy_pct}% vs año anterior`
    : 'Sin comparativa YoY disponible';
  bloqueIngresos = `
  <div style="display:flex; gap:12px; flex-wrap:wrap; margin: 14px 0 16px 0;">
    <div style="background:#eff6ff; border-radius:8px; padding:12px 16px; flex:1; min-width:140px; border:1px solid #dbeafe;">
      <div style="font-size:12px; color:#4b5563; font-weight:600;">Ingresos Previstos</div>
      <div style="font-size:20px; font-weight:bold; color:#1e3a8a; margin-top:2px;">${Number(ingresosResumen.totales_previstos).toLocaleString('es-ES', {minimumFractionDigits: 2, maximumFractionDigits: 2})} €</div>
    </div>
    <div style="background:#f0fdf4; border-radius:8px; padding:12px 16px; flex:1; min-width:140px; border:1px solid #dcfce7;">
      <div style="font-size:12px; color:#4b5563; font-weight:600;">Actuales (Confirmados)</div>
      <div style="font-size:20px; font-weight:bold; color:#166534; margin-top:2px;">${Number(ingresosResumen.totales_actuales ?? 0).toLocaleString('es-ES', {minimumFractionDigits: 2, maximumFractionDigits: 2})} €</div>
    </div>
    <div style="background:#fefce8; border-radius:8px; padding:12px 16px; flex:1; min-width:140px; border:1px solid #fef9c3;">
      <div style="font-size:12px; color:#4b5563; font-weight:600;">Año Anterior</div>
      <div style="font-size:20px; font-weight:bold; color:#854d0e; margin-top:2px;">${ingresosResumen.totales_anio_anterior !== null && ingresosResumen.totales_anio_anterior !== undefined ? Number(ingresosResumen.totales_anio_anterior).toLocaleString('es-ES', {minimumFractionDigits: 2, maximumFractionDigits: 2}) + ' €' : 'N/A'}</div>
    </div>
  </div>
  <p style="font-size:12px; color:#6b7280; margin:-8px 0 16px 2px;">
    <strong>Variación Ingresos:</strong> ${yoyTexto}${ingresosResumen.dias_sin_dato_yoy ? ` · ${ingresosResumen.dias_sin_dato_yoy} de ${ingresosResumen.dias_totales} días sin dato histórico comparable` : ''}
  </p>`;
}

// ----------------------------------------------------
// 4. GRÁFICAS: AJUSTE TARIFARIO (€)
// ----------------------------------------------------
const labelsDias = (Array.isArray(tablaDiaria) ? tablaDiaria : []).map(d => formatearFechaCorta(d.fecha));
const serieVariacionEur = tablaDiaria.map(d => {
  const act = parseFloat(d.adr_eur) || 0;
  const sug = parseFloat(d.adr_sugerido_eur) || 0;
  return (sug > 0 && act > 0) ? Number((sug - act).toFixed(2)) : 0;
});

const coloresBarras = serieVariacionEur.map(v => v >= 0 ? 'rgba(22, 163, 74, 0.7)' : 'rgba(220, 38, 38, 0.7)');
const bordesBarras = serieVariacionEur.map(v => v >= 0 ? '#16a34a' : '#dc2626');

const chartVariacionConfig = {
  type: 'bar',
  data: {
    labels: labelsDias,
    datasets: [{
      label: 'Ajuste Neto Tarifario (€)',
      data: serieVariacionEur,
      backgroundColor: coloresBarras,
      borderColor: bordesBarras,
      borderWidth: 1
    }]
  },
  options: {
    plugins: {
      title: { display: true, text: 'Ajuste Tarifario Sugerido vs Actual (€ por noche)' },
      legend: { display: false }
    },
    scales: {
      y: { ticks: { callback: (val) => val + ' €' } }
    }
  }
};
const chartVariacionUrl = `https://quickchart.io/chart?w=650&h=230&c=${encodeURIComponent(JSON.stringify(chartVariacionConfig))}`;

// ----------------------------------------------------
// 5. TABLA COMPARATIVA DIARIA (CUERPO)
// ----------------------------------------------------
const filasResumenPricing = tablaDiaria.map((d, i) => {
  const matchMetrica = serieDiariaMetricas.find(m => m.fecha === d.fecha);
  const ocupRealVal = d.ocupacion_actual ?? matchMetrica?.ocupacion?.actual ?? null;
  const ocupRealTxt = (ocupRealVal !== null && !isNaN(parseFloat(ocupRealVal)))
    ? (parseFloat(ocupRealVal) > 1 ? parseFloat(ocupRealVal).toFixed(1) : (parseFloat(ocupRealVal) * 100).toFixed(1)) + '%'
    : (d.ocupacion_pct ? pctDirecto(d.ocupacion_pct) : '-');

  const ocupPrevistaTxt = pctDirecto(d.ocupacion_pct);

  const tarifaReal = parseFloat(d.adr_eur) || 0;
  const tarifaPropuesta = parseFloat(d.adr_sugerido_eur) || tarifaReal;
  const dif = tarifaPropuesta - tarifaReal;
  const difTxt = dif !== 0 
    ? `<strong style="color:${dif > 0 ? '#166534' : '#991b1b'}">${dif > 0 ? '+' : ''}${dif.toFixed(2)} €</strong>` 
    : '<span style="color:#6b7280">0.00 €</span>';

  return `
    <tr style="${i % 2 === 1 ? 'background:#f9fafb;' : ''}">
      <td style="padding:6px; border:1px solid #d1d5db;">${formatearFechaCorta(d.fecha)}</td>
      <td style="padding:6px; text-align:center; border:1px solid #d1d5db; font-weight:bold;">${ocupRealTxt}</td>
      <td style="padding:6px; text-align:center; border:1px solid #d1d5db;">${ocupPrevistaTxt}</td>
      <td style="padding:6px; text-align:center; border:1px solid #d1d5db;">${d.pickup_7 ?? '0'}</td>
      <td style="padding:6px; text-align:center; border:1px solid #d1d5db;">${tarifaReal.toFixed(2)} €</td>
      <td style="padding:6px; text-align:center; border:1px solid #d1d5db; font-weight:bold; color:#1e3a8a;">${tarifaPropuesta.toFixed(2)} €</td>
      <td style="padding:6px; text-align:center; border:1px solid #d1d5db;">${difTxt}</td>
    </tr>`;
}).join('');

// ----------------------------------------------------
// 6. HISTÓRICO Y COMPETENCIA
// ----------------------------------------------------
const adrPropio = Number(
  totalPeriodo.ingresos?.adr_medio ||
  est?.adr_medio ||
  (Array.isArray(tablaDiaria) && tablaDiaria.length > 0 
    ? tablaDiaria.reduce((acc, d) => acc + (Number(d.adr_eur) || 0), 0) / tablaDiaria.length 
    : 0)
);
const revparPropio = Number(
  totalPeriodo.ingresos?.revpar_medio ||
  (Array.isArray(tablaDiaria) && tablaDiaria.length > 0
    ? tablaDiaria.reduce((acc, d) => acc + (Number(d.revpar_eur) || 0), 0) / tablaDiaria.length
    : 0)
);
const ocupPropia = est?.media ? (est.media * 100).toFixed(1) : (totalPeriodo.ocupacion?.prevista_media ?? 0).toFixed(1);
const miRatingFijo = 4.7;

let bloqueCompetencia = '';
if (Array.isArray(tablaCompetencia) && tablaCompetencia.length > 0) {
  const filasComp = tablaCompetencia.map((h, i) => {
    const precioVal = extraerPrecioNumerico(h.precio ?? h.tarifa ?? h.rate ?? h.price);
    let precioDisplay = precioVal !== null ? precioVal.toFixed(2) + ' €' : '<span style="color:#9ca3af;">Consultar</span>';

    let comparativaPrecio = '<span style="color:#9ca3af; font-size:11px;">Sin datos</span>';
    if (precioVal !== null && adrPropio > 0) {
      const dif = precioVal - adrPropio;
      comparativaPrecio = dif > 0 
        ? `<span style="color:#991b1b; font-size:11px; font-weight:bold;">▲ +${dif.toFixed(2)} €<br>(Más caro)</span>`
        : `<span style="color:#166534; font-size:11px; font-weight:bold;">▼ ${dif.toFixed(2)} €<br>(Más barato)</span>`;
    }

    let ratingVal = parseFloat(h.rating);
    let comparativaRating = '<span style="color:#9ca3af; font-size:11px;">Sin datos</span>';
    if (!isNaN(ratingVal) && ratingVal > 0) {
      const difR = Number((ratingVal - miRatingFijo).toFixed(1));
      comparativaRating = difR > 0 
        ? `<span style="color:#991b1b; font-size:11px; font-weight:bold;">▲ +${difR}<br>(Superior)</span>`
        : (difR < 0 ? `<span style="color:#166534; font-size:11px; font-weight:bold;">▼ ${difR}<br>(Inferior)</span>` : `<span style="color:#4b5563; font-size:11px;">= Igual</span>`);
    }

    return `
    <tr style="${i % 2 === 1 ? 'background:#f9fafb;' : ''}">
      <td style="padding:6px; border:1px solid #d1d5db;">${h.nombre}</td>
      <td style="padding:6px; text-align:center; border:1px solid #d1d5db; font-weight:bold;">⭐ ${!isNaN(ratingVal) ? ratingVal.toFixed(1) : 'N/A'}</td>
      <td style="padding:6px; text-align:center; border:1px solid #d1d5db;">${comparativaRating}</td>
      <td style="padding:6px; text-align:center; border:1px solid #d1d5db;">${h.resenas ?? h.numResenas ?? 'N/A'}</td>
      <td style="padding:6px; text-align:center; border:1px solid #d1d5db; font-weight:bold;">${precioDisplay}</td>
      <td style="padding:6px; text-align:center; border:1px solid #d1d5db;">${comparativaPrecio}</td>
    </tr>`;
  }).join('');

  bloqueCompetencia = `
  <h2 style="color:#1e3a8a; margin-top:24px; font-size:16px;">Posicionamiento frente a la competencia (Baiona)</h2>
  <p style="font-size:12px; color:#6b7280; margin:4px 0 8px 0;">Comparativa contra nuestras métricas de referencia: <strong>ADR ${adrPropio.toFixed(2)} €</strong> y <strong>Rating ⭐ ${miRatingFijo.toFixed(1)}</strong>.</p>
  <div style="overflow-x:auto;">
    <table style="width:100%; border-collapse:collapse; font-size:12px;">
      <tr style="background:#eff6ff;">
        <th style="text-align:left; padding:6px; border:1px solid #d1d5db;">Hotel Competidor</th>
        <th style="padding:6px; border:1px solid #d1d5db;">Rating</th>
        <th style="padding:6px; border:1px solid #d1d5db;">Vs Nuestro Rating</th>
        <th style="padding:6px; border:1px solid #d1d5db;">Nº Reseñas</th>
        <th style="padding:6px; border:1px solid #d1d5db;">Precio</th>
        <th style="padding:6px; border:1px solid #d1d5db;">Vs Nuestro ADR</th>
      </tr>
      ${filasComp}
    </table>
  </div>`;
}

let bloqueHistorico = '';
if (Array.isArray(tablaHistorico) && tablaHistorico.length > 0) {
  const filasHist = tablaHistorico.map((p, i) => {
    const difOcup = (Number(ocupPropia) - Number(p.ocupacion_media)).toFixed(1);
    const difAdr = (Number(adrPropio) - Number(p.adr)).toFixed(2);
    const difRevpar = (Number(revparPropio) - Number(p.revpar)).toFixed(2);
    const fmtDif = (v, s = '') => `${Number(v) >= 0 ? '+' : ''}${v}${s}`;
    const estiloDif = (v) => Number(v) >= 0 ? 'color:#166534;' : 'color:#991b1b;';

    return `
    <tr style="${i % 2 === 1 ? 'background:#f9fafb;' : ''}">
      <td style="padding:6px; border:1px solid #d1d5db;">${p.periodo}</td>
      <td style="padding:6px; text-align:center; border:1px solid #d1d5db;">${p.ocupacion_media}% <br><span style="font-size:10px; ${estiloDif(difOcup)}">(${fmtDif(difOcup, ' pp')})</span></td>
      <td style="padding:6px; text-align:center; border:1px solid #d1d5db;">${p.adr} € <br><span style="font-size:10px; ${estiloDif(difAdr)}">(${fmtDif(difAdr, ' €')})</span></td>
      <td style="padding:6px; text-align:center; border:1px solid #d1d5db;">${p.revpar} € <br><span style="font-size:10px; ${estiloDif(difRevpar)}">(${fmtDif(difRevpar, ' €')})</span></td>
      <td style="padding:6px; text-align:center; border:1px solid #d1d5db;">${p.pickup_7}</td>
      <td style="padding:6px; text-align:center; border:1px solid #d1d5db;">${p.pct_festivos}% / ${p.pct_vacaciones}%</td>
      <td style="padding:6px; text-align:center; border:1px solid #d1d5db;"><strong>${p.similitud !== null ? (p.similitud * 100).toFixed(0) + '%' : 'N/A'}</strong></td>
    </tr>`;
  }).join('');

  bloqueHistorico = `
  <h2 style="color:#1e3a8a; margin-top:24px; font-size:16px;">Comparativa con Periodos Históricos Similares</h2>
  <p style="font-size:12px; color:#6b7280; margin:4px 0 8px 0;">Comparación del periodo previsto frente a las semanas históricas más equiparables (K-NN). Entre paréntesis: diferencia vs situación actual.</p>
  <div style="overflow-x:auto;">
    <table style="width:100%; border-collapse:collapse; font-size:12px;">
      <tr style="background:#eff6ff;">
        <th style="text-align:left; padding:6px; border:1px solid #d1d5db;">Periodo</th>
        <th style="padding:6px; border:1px solid #d1d5db;">Ocupación</th>
        <th style="padding:6px; border:1px solid #d1d5db;">ADR</th>
        <th style="padding:6px; border:1px solid #d1d5db;">RevPAR</th>
        <th style="padding:6px; border:1px solid #d1d5db;">Pickup 7d</th>
        <th style="padding:6px; border:1px solid #d1d5db;">Festivos/Vac.</th>
        <th style="padding:6px; border:1px solid #d1d5db;">Similitud</th>
      </tr>
      <tr style="background:#ecfdf5; font-weight:bold;">
        <td style="padding:6px; border:1px solid #d1d5db; color:#065f46;">📍 Periodo Previsto (Actual)</td>
        <td style="padding:6px; text-align:center; border:1px solid #d1d5db; color:#065f46;">${ocupPropia}%</td>
        <td style="padding:6px; text-align:center; border:1px solid #d1d5db; color:#065f46;">${adrPropio.toFixed(2)} €</td>
        <td style="padding:6px; text-align:center; border:1px solid #d1d5db; color:#065f46;">${revparPropio.toFixed(2)} €</td>
        <td style="padding:6px; text-align:center; border:1px solid #d1d5db; color:#065f46;">${pickupPropio}</td>
        <td style="padding:6px; text-align:center; border:1px solid #d1d5db; color:#065f46;">-</td>
        <td style="padding:6px; text-align:center; border:1px solid #d1d5db; color:#065f46;">Base</td>
      </tr>
      ${filasHist}
    </table>
  </div>`;
}
// ----------------------------------------------------
// 7. ANEXO: TABLAS SEGMENTADAS ORDENADAS + GRÁFICAS
// ----------------------------------------------------
