const totalDiasPeriodo = Array.isArray(tablaDiaria) && tablaDiaria.length > 0 ? tablaDiaria.length : 14;

function normalizarSegmento(items, defaults) {
  const lista = Array.isArray(items) && items.length > 0 ? items : defaults;
  return lista.map(it => {
    const porcentaje = Number(it.pct) || 0;
    const diasCalculados = it.dias ? it.dias : Math.max(1, Math.round((porcentaje / 100) * totalDiasPeriodo));
    return {
      valor: it.valor,
      dias: diasCalculados,
      pct: porcentaje
    };
  });
}

