function renderTablaTarjeta(titulo, icono, items, colorBarra) {
  const filas = items.map(item => `
    <tr>
      <td style="padding:6px 8px; border-bottom:1px solid #f1f5f9; font-size:12px; color:#1f2937;">
        ${item.valor}
        <div style="background:#e2e8f0; border-radius:3px; height:4px; width:100%; margin-top:3px;">
          <div style="background:${colorBarra}; height:4px; border-radius:3px; width:${item.pct}%;"></div>
        </div>
      </td>
      <td style="padding:6px 8px; text-align:center; border-bottom:1px solid #f1f5f9; font-size:12px; color:#4b5563; white-space:nowrap;">
        ${item.dias}d
      </td>
      <td style="padding:6px 8px; text-align:right; border-bottom:1px solid #f1f5f9; font-size:12px; font-weight:bold; color:#1e3a8a; white-space:nowrap;">
        ${item.pct}%
      </td>
    </tr>
  `).join('');

  return `
    <div style="flex:1; min-width:240px; background:#ffffff; border:1px solid #e2e8f0; border-radius:8px; overflow:hidden; box-shadow:0 1px 2px rgba(0,0,0,0.03);">
