            <th style="padding:5px 8px; text-align:center;">Días</th>
            <th style="padding:5px 8px; text-align:right;">Cuota</th>
          </tr>
        </thead>
        <tbody>
          ${filas}
        </tbody>
      </table>
    </div>
  `;
}

